step3_testbench.spice:
* Quadrature Ring VCO Testbench
.lib "${SKY130_PDK}" tt

.param W_xm1=5u L_xm1=0.5u
.param W_xm2=5u L_xm2=0.5u
.param W_xm3=5u L_xm3=0.5u
.param W_xm7=5u L_xm7=0.5u
.param W_xm4=5u L_xm4=0.5u
.param W_xm6=5u L_xm6=0.5u
.param W_xm8=5u L_xm8=0.5u
.param W_xm5=5u L_xm5=0.5u

.param I_latch = 1m
.param I_inject = 1m
.param R_load = 500
.param C_load = 100f

VVDD VDD 0 1.8

* Loads
R1 0_DEG VDD {R_load}
R2 180_DEG VDD {R_load}
R3 90_DEG VDD {R_load}
R4 270_DEG VDD {R_load}

* Parasitic/Tuning Capacitors
C1 0_DEG 0 {C_load}
C2 180_DEG 0 {C_load}
C3 90_DEG 0 {C_load}
C4 270_DEG 0 {C_load}

* Tail Current Sources for Tuning
I_A A 0 {I_latch}
I_B B 0 {I_latch}
I_C C 0 {I_inject}
I_D D 0 {I_inject}

* DUT
XM1 0_DEG 180_DEG A GND sky130_fd_pr__nfet_01v8 l={L_xm1} w={W_xm1}
XM2 180_DEG 0_DEG A GND sky130_fd_pr__nfet_01v8 l={L_xm2} w={W_xm2}
XM3 270_DEG 90_DEG B GND sky130_fd_pr__nfet_01v8 l={L_xm3} w={W_xm3}
XM7 270_DEG 180_DEG D GND sky130_fd_pr__nfet_01v8 l={L_xm7} w={W_xm7}
XM4 90_DEG 270_DEG B GND sky130_fd_pr__nfet_01v8 l={L_xm4} w={W_xm4}
XM6 180_DEG 90_DEG C GND sky130_fd_pr__nfet_01v8 l={L_xm6} w={W_xm6}
XM8 90_DEG 0_DEG D GND sky130_fd_pr__nfet_01v8 l={L_xm8} w={W_xm8}
XM5 0_DEG 270_DEG C GND sky130_fd_pr__nfet_01v8 l={L_xm5} w={W_xm5}

* Initial conditions to kickstart oscillation
.ic v(0_DEG)=1.8 v(180_DEG)=0 v(90_DEG)=0.9 v(270_DEG)=0.9

.control
tran 10p 20n

* Measure frequency
meas tran t1 trig v(0_DEG) val=1.3 rise=5 targ v(0_DEG) val=1.3 rise=6
let freq = 1 / t1
print freq

* Measure amplitude
meas tran vmax max v(0_DEG) from=10n to=20n
meas tran vmin min v(0_DEG) from=10n to=20n
let vpp = vmax - vmin
print vpp

* Measure phase difference (should be 90 degrees)
meas tran t_90 trig v(0_DEG) val=1.3 rise=5 targ v(270_DEG) val=1.3 rise=5
let phase_diff = (t_90 / t1) * 360
print phase_diff

* Measure power consumption
meas tran pwr avg i(VVDD) from=10n to=20n
let power_mw = -pwr * 1.8 * 1000
print power_mw

quit
.endc

